export const money=n=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);
export const estimate=(ids,vehicle)=>services.filter(s=>ids.includes(s.id)).reduce((n,s)=>n+s.price,0)*(vehicle==='SUV'?1.2:1);
export const cartTotal=cart=>products.reduce((n,p)=>n+p.price*(cart[p.id]||0),0);
const empty=()=>({cart:{},bookings:[],orders:[],favorites:[],vehicle:'Седан',services:[]});
let state=empty();try{const v=JSON.parse(sessionStorage.getItem('wl-demo-v1'));if(v&&v.cart&&Array.isArray(v.bookings)&&Array.isArray(v.orders)&&Array.isArray(v.favorites)&&Array.isArray(v.services))state={...state,...v}}catch{}
export const getState=()=>state;
export function save(){try{sessionStorage.setItem('wl-demo-v1',JSON.stringify(state));return true}catch{return false}}
export function reset(){state=empty();save()}
export function book(slot){if(!state.services.length)throw Error('Выберите хотя бы одну услугу.');if(state.bookings.some(b=>b.slot===slot&&b.status!=='Отменено'))throw Error('Это время уже занято в вашей демосессии.');const b={id:crypto.randomUUID(),slot,vehicle:state.vehicle,services:[...state.services],total:estimate(state.services,state.vehicle),status:'Новая'};state.bookings.unshift(b);save();return b}
export function checkout(){if(!cartTotal(state.cart))throw Error('Корзина пуста.');const o={id:crypto.randomUUID(),items:{...state.cart},total:cartTotal(state.cart),status:'Новый'};state.orders.unshift(o);state.cart={};save();return o}
